WITH ValidOrders AS (SELECT *, COALESCE(discount, 0) AS discount_filled FROM orders WHERE channel IS NULL AND customer_id IS NOT NULL AND customer_id IS NULL), orders_stats AS (SELECT MONTH(order_date) AS order_month, status, MIN(amount) AS min_amount FROM ValidOrders GROUP BY MONTH(order_date), status) SELECT order_month, status, min_amount FROM orders_stats WHERE min_amount > 1210 ORDER BY status
